-- 172: הזמנת פודיום — the core squad's nutrition order from Podium (lib/podium, Ofer 10-26).
-- Mockup ~/.cache/madregot/mockups/podium-order/index.html.
--   podium_products     the catalog ("מדרגות תזונה 5"), with the site's price/deal/photo (checked 10-26)
--   podium_rounds       one club order: who it's for, opens_at → locks_at (no changes after), budget per runner, sent_at
--   podium_orders       one per runner per round; approval when over the budget (the runner pays the rest)
--   podium_order_items  quantities
-- Service role only (no policies). Paste as one block; safe to run twice.

CREATE TABLE IF NOT EXISTS podium_products (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  sku           INTEGER NOT NULL UNIQUE,      -- "פריט" in Podium's sheet
  barcode       TEXT NOT NULL,
  name          TEXT NOT NULL,
  dept          TEXT NOT NULL,                -- "שם מחלקה"
  url           TEXT,                         -- the product page on podiumsport.co.il
  image_url     TEXT,
  price         NUMERIC(10,2),                -- the site's price; NULL = not found on the site
  regular_price NUMERIC(10,2),                -- struck-through "מחיר רגיל", when on sale
  deal          TEXT,                         -- "קנו 10 קבלו 1 חינם"
  hidden        BOOLEAN NOT NULL DEFAULT false,
  checked_at    TIMESTAMPTZ,
  sort          INTEGER NOT NULL DEFAULT 0,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
ALTER TABLE podium_products ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS podium_rounds (
  id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  title              TEXT NOT NULL,
  opens_at           TIMESTAMPTZ NOT NULL,
  locks_at           TIMESTAMPTZ NOT NULL,
  budget             NUMERIC(10,2) NOT NULL DEFAULT 600,
  -- Who may order: 'me' (only whoever opened it — a dry run), 'admins', 'people' (audience_ids),
  -- 'core' (the גרעין), 'all'. Staff always manage it from the admin screen.
  audience           TEXT NOT NULL DEFAULT 'core' CHECK (audience IN ('me','admins','people','core','all')),
  audience_ids       UUID[] NOT NULL DEFAULT '{}',
  sent_at            TIMESTAMPTZ,             -- the admin sent the file to Podium
  notified_open_ids  UUID[] NOT NULL DEFAULT '{}', -- the push ledger (cron/tick): who already got "it's open"
  notified_remind_at TIMESTAMPTZ,
  notified_lock_at   TIMESTAMPTZ,
  created_by         UUID,
  created_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS podium_rounds_opens ON podium_rounds (opens_at DESC);
ALTER TABLE podium_rounds ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS podium_orders (
  id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  round_id       UUID NOT NULL REFERENCES podium_rounds(id) ON DELETE CASCADE,
  athlete_id     UUID NOT NULL REFERENCES athletes(id) ON DELETE CASCADE,
  submitted_at   TIMESTAMPTZ,                 -- NULL = a draft
  approval       TEXT NOT NULL DEFAULT 'none' CHECK (approval IN ('none','pending','approved','rejected')),
  approved_total NUMERIC(10,2),               -- the total the yes was given for
  approved_by    UUID,
  approved_at    TIMESTAMPTZ,
  updated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by     UUID,                        -- who changed it last (an admin's edit is told to the runner)
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (round_id, athlete_id)
);
ALTER TABLE podium_orders ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS podium_order_items (
  order_id   UUID NOT NULL REFERENCES podium_orders(id) ON DELETE CASCADE,
  product_id UUID NOT NULL REFERENCES podium_products(id) ON DELETE CASCADE,
  quantity   INTEGER NOT NULL CHECK (quantity > 0 AND quantity < 100),
  PRIMARY KEY (order_id, product_id)
);
ALTER TABLE podium_order_items ENABLE ROW LEVEL SECURITY;

ON CONFLICT (sku) DO NOTHING;
